"""ORD_LINE renumbering migration for Meridian CRM 4.2."""

from collections import defaultdict
from typing import Any


def _numeric_line_no(value: Any) -> float:
    """Return a numeric sort key, preserving legacy empty-as-zero behavior."""
    if value == "":
        return 0.0
    try:
        return float(value)
    except (TypeError, ValueError):
        return 0.0


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted lines and assign contiguous line numbers per order.

    Surviving rows are ordered within each order by their original LINE_NO
    numerically. Returned rows and dictionaries are newly created.
    """
    orders: dict[str, list[tuple[int, dict]]] = defaultdict(list)

    for input_index, row in enumerate(lines):
        if row.get("DEL_FLG", "") == "Y":
            continue
        order_id = str(row.get("ORD_ID", ""))
        orders[order_id].append((input_index, row))

    result: list[dict] = []

    for order_id in sorted(orders):
        ordered_rows = sorted(
            orders[order_id],
            key=lambda item: (_numeric_line_no(item[1].get("LINE_NO", "")), item[0]),
        )
        for line_no, (_, row) in enumerate(ordered_rows, start=1):
            copied_row = dict(row)
            copied_row["LINE_NO"] = line_no
            result.append(copied_row)

    return result
